/* If findRecipients=False then iterate over keys of recipientNotificationData, and for each recipientId, If the recipientId is not present in sendToRecipients then remove it from the recipientNotificationData json ELSE Remove the recipeintId  from sendToRecipients list (the recipientId now becomes eligible for individual email)
*/

let recipientNotificationDataJson = JSON.parse(`#{recipientNotificationDataFinal}`);
let sendToRecipientsJson = JSON.parse(`#{sendToRecipients}`);
let recipientNotificationDataOut = {};

for (const [recipientId, value] of Object.entries(recipientNotificationDataJson)) {
  let arrindex = sendToRecipientsJson.indexOf(recipientId);
  if( arrindex== -1 ){ 
  //check if only mobile no exists and not with countrycode etc
    if(recipientId.length >=10 && recipientId.length<=15){
       //assume it is phone
        let last10 = recipientId.slice(-10);
        if(sendToRecipientsJson.indexOf(last10) ==-1){ //remove it from out array
        } else {
          recipientNotificationDataOut[recipientId]=value;
          sendToRecipientsJson.splice(arrindex,1); //remove from sendToRecipients
        }
     } else { //remove it from out array, this is email
    }
  }  else {
    recipientNotificationDataOut[recipientId]=value;
   sendToRecipientsJson.splice(arrindex,1); //remove from sendToRecipients
  }   
}

